<?php
require_once __DIR__ . '/../includes/bootstrap.php';
require_role('programme_manager');
require_once __DIR__ . '/_management_suite_helpers.php';
$user=current_user();$conn=Database::getConnection();$managerId=(int)($user['id']??$user['user_id']??0);if($managerId<=0){http_response_code(403);exit('Invalid Programme Manager account.');}
$currentPage='risks';$pageTitle='Risk Register';$flashes=render_flashes();$errors=[];$tableReady=pm_table_exists($conn,'programme_risks');$programmes=pm_suite_programmes($conn,$managerId);$cohorts=pm_suite_cohorts($conn,$managerId);

$statuses=['open'=>'Open','mitigating'=>'Mitigation in progress','monitoring'=>'Monitoring','resolved'=>'Resolved','accepted'=>'Accepted'];$editing=['id'=>0,'programme_id'=>0,'cohort_id'=>0,'title'=>'','description'=>'','category'=>'Operational','likelihood'=>3,'impact'=>3,'mitigation_plan'=>'','owner_name'=>'','due_date'=>'','status'=>'open'];
if($_SERVER['REQUEST_METHOD']==='POST'){if(!validate_csrf())$errors[]='Session validation failed. Refresh and try again.';elseif(!$tableReady)$errors[]='Import database/programme_management_suite.sql before managing risks.';else{$action=(string)($_POST['action']??'save');$id=(int)($_POST['risk_id']??0);if($action==='delete'){$s=$conn->prepare('DELETE r FROM programme_risks r JOIN programmes p ON p.id=r.programme_id WHERE r.id=? AND p.programme_manager_id=?');if($s){$s->bind_param('ii',$id,$managerId);$s->execute();$deleted=$s->affected_rows>0;$s->close();if($deleted){set_flash('success','Risk deleted','The risk record has been removed.');safe_redirect('programme/risks.php');}}$errors[]='The risk was not found in your assigned programme scope.';}else{$pid=(int)($_POST['programme_id']??0);$cid=(int)($_POST['cohort_id']??0);$title=trim((string)($_POST['title']??''));$desc=trim((string)($_POST['description']??''));$category=trim((string)($_POST['category']??'Operational'));$likelihood=(int)($_POST['likelihood']??3);$impact=(int)($_POST['impact']??3);$mitigation=trim((string)($_POST['mitigation_plan']??''));$owner=trim((string)($_POST['owner_name']??''));$due=trim((string)($_POST['due_date']??''));$status=(string)($_POST['status']??'open');if(!pm_suite_valid_scope($conn,$pid,$cid,$managerId))$errors[]='Choose a programme/cohort within your assigned scope.';if($title===''||mb_strlen($title)>180)$errors[]='Enter a risk title of up to 180 characters.';if($category===''||strlen($category)>80)$errors[]='Enter a category of up to 80 characters.';if($likelihood<1||$likelihood>5||$impact<1||$impact>5)$errors[]='Likelihood and impact must be between 1 and 5.';if(!isset($statuses[$status]))$errors[]='Choose a valid risk status.';if($due!==''){ $d=DateTime::createFromFormat('!Y-m-d',$due);if(!$d||$d->format('Y-m-d')!==$due)$errors[]='Choose a valid mitigation due date.';}if($id>0){$s=$conn->prepare('SELECT r.id FROM programme_risks r JOIN programmes p ON p.id=r.programme_id WHERE r.id=? AND p.programme_manager_id=?');$owned=false;if($s){$s->bind_param('ii',$id,$managerId);$s->execute();$owned=(bool)$s->get_result()->fetch_assoc();$s->close();}if(!$owned)$errors[]='You cannot edit a risk outside your assigned scope.';}if(!$errors){$cv=$cid?:null;$duev=$due?:null;$ownerv=$owner?:null;if($id>0){$s=$conn->prepare('UPDATE programme_risks SET programme_id=?,cohort_id=?,title=?,description=?,category=?,likelihood=?,impact=?,mitigation_plan=?,owner_name=?,due_date=?,status=? WHERE id=?');if($s)$s->bind_param('iisssiissssi',$pid,$cv,$title,$desc,$category,$likelihood,$impact,$mitigation,$ownerv,$duev,$status,$id);}else{$s=$conn->prepare('INSERT INTO programme_risks(programme_id,cohort_id,title,description,category,likelihood,impact,mitigation_plan,owner_name,due_date,status,created_by) VALUES(?,?,?,?,?,?,?,?,?,?,?,?)');if($s)$s->bind_param('iisssiissssi',$pid,$cv,$title,$desc,$category,$likelihood,$impact,$mitigation,$ownerv,$duev,$status,$managerId);}if(isset($s)&&$s){$ok=$s->execute();$s->close();if($ok){set_flash('success',$id?'Risk updated':'Risk recorded','Risk and mitigation details have been saved.');safe_redirect('programme/risks.php');}}$errors[]='The risk could not be saved.';}}}}
$editId=(int)($_GET['edit']??0);if($tableReady&&$editId){$s=$conn->prepare('SELECT r.* FROM programme_risks r JOIN programmes p ON p.id=r.programme_id WHERE r.id=? AND p.programme_manager_id=?');if($s){$s->bind_param('ii',$editId,$managerId);$s->execute();$found=$s->get_result()->fetch_assoc();$s->close();if($found)$editing=$found;}}
$risks=[];$riskStats=['total'=>0,'open'=>0,'critical'=>0,'overdue'=>0];if($tableReady){$s=$conn->prepare("SELECT r.*,p.name programme_name,c.name cohort_name,(r.likelihood*r.impact) score,CASE WHEN r.due_date<CURDATE() AND r.status NOT IN ('resolved','accepted') THEN 1 ELSE 0 END overdue FROM programme_risks r JOIN programmes p ON p.id=r.programme_id LEFT JOIN cohorts c ON c.id=r.cohort_id WHERE p.programme_manager_id=? ORDER BY (r.likelihood*r.impact) DESC,r.due_date ASC");if($s){$s->bind_param('i',$managerId);$s->execute();$risks=$s->get_result()->fetch_all(MYSQLI_ASSOC);$s->close();}foreach($risks as $r){$riskStats['total']++;if(!in_array($r['status'],['resolved','accepted'],true))$riskStats['open']++;if((int)$r['score']>=15&& !in_array($r['status'],['resolved','accepted'],true))$riskStats['critical']++;if((int)$r['overdue'])$riskStats['overdue']++;}}
?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title><?=e($pageTitle)?> | Investhood IT</title><link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.5.1/css/all.min.css"><link rel="stylesheet" href="<?=url('css/styles.css')?>"><link rel="stylesheet" href="<?=url('css/programme_manager_enhancements.css')?>?v=20261026"><link rel="stylesheet" href="<?=url('css/programme_management_suite.css')?>?v=20261026"></head><body class="dashboard-page"><div class="dashboard"><?php require __DIR__.'/sidebar.php';?><main class="dashboard__main"><?php require __DIR__.'/navbar.php';?><div class="pm-suite"><?=$flashes?>

<section class="pm-suite-hero"><div><span class="pm-suite-eyebrow">Programme assurance</span><h1>Risk Register &amp; Mitigation Tracking</h1><p>Record delivery risks, assess likelihood and impact, assign an owner, and monitor mitigation actions across assigned programmes and cohorts.</p></div><a class="pm-suite-btn" href="#riskForm"><i class="fas fa-plus"></i> Record risk</a></section><?php foreach($errors as $error):?><div class="pm-suite-alert"><?=e($error)?></div><?php endforeach;?><?php if(!$tableReady):?><div class="pm-suite-notice">Import <code>database/programme_management_suite.sql</code> to enable risk tracking.</div><?php endif;?>
<section class="pm-suite-kpis"><article class="pm-suite-kpi"><small>Total risks</small><strong><?=$riskStats['total']?></strong><span>Across assigned programmes</span></article><article class="pm-suite-kpi"><small>Open risks</small><strong><?=$riskStats['open']?></strong><span>Not resolved or accepted</span></article><article class="pm-suite-kpi"><small>High / critical</small><strong><?=$riskStats['critical']?></strong><span>Risk score 15–25</span></article><article class="pm-suite-kpi"><small>Overdue mitigation</small><strong><?=$riskStats['overdue']?></strong><span>Past due and still active</span></article></section>
<div class="pm-suite-grid"><section class="pm-suite-panel" id="riskForm"><div class="pm-suite-panel-head"><h2><?=$editing['id']?'Edit risk':'Record a risk'?></h2><p>Risk score is calculated from likelihood × impact (each rated 1–5).</p></div><form class="pm-suite-form" method="post"><?=csrf_field()?><input type="hidden" name="action" value="save"><input type="hidden" name="risk_id" value="<?=(int)$editing['id']?>"><div class="pm-suite-field"><label>Programme</label><select name="programme_id" required><option value="">Select programme</option><?php foreach($programmes as $p):?><option value="<?=$p['id']?>" <?=((int)$editing['programme_id']===(int)$p['id'])?'selected':''?>><?=e($p['name'])?></option><?php endforeach;?></select></div><div class="pm-suite-field"><label>Cohort (optional)</label><select name="cohort_id"><option value="0">Programme-wide</option><?php foreach($cohorts as $c):?><option value="<?=$c['id']?>" <?=((int)($editing['cohort_id']??0)===(int)$c['id'])?'selected':''?>><?=e($c['programme_name'].' — '.$c['name'])?></option><?php endforeach;?></select></div><div class="pm-suite-field"><label>Risk title</label><input name="title" maxlength="180" required value="<?=e($editing['title'])?>" placeholder="e.g. Candidate attendance below target"></div><div class="pm-suite-field"><label>Description / potential impact</label><textarea name="description" rows="3" maxlength="5000"><?=e((string)($editing['description']??''))?></textarea></div><div class="pm-suite-field"><label>Category</label><select name="category"><?php foreach(['Operational','Candidate progression','Attendance','Cohort capacity','Financial','Compliance','Staffing','Technology','Other'] as $cat):?><option <?=($editing['category']===$cat)?'selected':''?>><?=e($cat)?></option><?php endforeach;?></select></div><div class="pm-suite-two"><div class="pm-suite-field"><label>Likelihood (1–5)</label><select name="likelihood"><?php for($i=1;$i<=5;$i++):?><option value="<?=$i?>" <?=(int)$editing['likelihood']===$i?'selected':''?>><?=$i?> — <?=$i===1?'Rare':($i===2?'Unlikely':($i===3?'Possible':($i===4?'Likely':'Almost certain')))?></option><?php endfor;?></select></div><div class="pm-suite-field"><label>Impact (1–5)</label><select name="impact"><?php for($i=1;$i<=5;$i++):?><option value="<?=$i?>" <?=(int)$editing['impact']===$i?'selected':''?>><?=$i?> — <?=$i===1?'Minimal':($i===2?'Minor':($i===3?'Moderate':($i===4?'Major':'Severe')))?></option><?php endfor;?></select></div></div><div class="pm-suite-field"><label>Mitigation plan</label><textarea name="mitigation_plan" rows="3" maxlength="5000"><?=e((string)($editing['mitigation_plan']??''))?></textarea></div><div class="pm-suite-field"><label>Responsible owner</label><input name="owner_name" maxlength="150" value="<?=e((string)($editing['owner_name']??''))?>" placeholder="Name or responsible role"></div><div class="pm-suite-two"><div class="pm-suite-field"><label>Mitigation due date</label><input type="date" name="due_date" value="<?=e((string)($editing['due_date']??''))?>"></div><div class="pm-suite-field"><label>Status</label><select name="status"><?php foreach($statuses as $k=>$v):?><option value="<?=e($k)?>" <?=$editing['status']===$k?'selected':''?>><?=e($v)?></option><?php endforeach;?></select></div></div><div class="pm-suite-actions"><button class="pm-suite-btn" type="submit" <?=$tableReady?'':'disabled'?>><?=$editing['id']?'Save changes':'Save risk'?></button><?php if($editing['id']):?><a class="pm-suite-btn secondary" href="<?=url('programme/risks.php')?>">Cancel</a><?php endif;?></div></form></section>
<section class="pm-suite-panel"><div class="pm-suite-panel-head"><h2>Risk register</h2><p>Prioritised by risk score and mitigation deadline.</p></div><div class="pm-suite-table-wrap"><table class="pm-suite-table"><thead><tr><th>Risk / scope</th><th>Score</th><th>Mitigation owner / due</th><th>Status</th><th>Actions</th></tr></thead><tbody><?php if(!$risks):?><tr><td colspan="5" class="pm-suite-empty">No risks recorded yet.</td></tr><?php else:foreach($risks as $r):$score=(int)$r['score'];?><tr><td><strong><?=e($r['title'])?></strong><span class="pm-suite-muted"><?=e($r['programme_name'])?><?=!empty($r['cohort_name'])?' · '.e($r['cohort_name']):' · Programme-wide'?> · <?=e($r['category'])?></span><span class="pm-suite-muted"><?=e(mb_strimwidth((string)$r['mitigation_plan'],0,120,'…'))?></span></td><td><span class="pm-suite-pill <?=$score>=15?'bad':($score>=8?'warn':'good')?>"><?=$score?> / 25</span><span class="pm-suite-muted">L <?=$r['likelihood']?> × I <?=$r['impact']?></span></td><td><?=e($r['owner_name']?:'Unassigned')?><span class="pm-suite-muted"><?=!empty($r['due_date'])?e(date('d M Y',strtotime($r['due_date']))):'No due date'?></span><?php if((int)$r['overdue']):?><span class="pm-suite-pill bad">Overdue</span><?php endif;?></td><td><span class="pm-suite-pill <?=in_array($r['status'],['resolved','accepted'])?'good':($r['status']==='mitigating'?'info':'warn')?>"><?=e($statuses[$r['status']]??$r['status'])?></span></td><td><div class="pm-suite-inline"><a class="pm-suite-btn secondary" href="<?=url('programme/risks.php?edit='.(int)$r['id'])?>">Edit</a><form method="post" onsubmit="return confirm('Delete this risk record?')"><?=csrf_field()?><input type="hidden" name="action" value="delete"><input type="hidden" name="risk_id" value="<?=$r['id']?>"><button class="pm-suite-btn danger" type="submit">Delete</button></form></div></td></tr><?php endforeach;endif;?></tbody></table></div></section></div>
</div></main></div><script src="<?=url('js/programme_manager_enhancements.js')?>?v=20261026"></script><script src="<?=url('js/original_pm_sidebar.js')?>?v=20261026"></script></body></html>
